// src/WalletPage.js
import React, { useState } from 'react';
import { ethers, BrowserProvider } from 'ethers';

function WalletPage() {
  const [privateKey, setPrivateKey] = useState('');
  const [wallet, setWallet] = useState(null);
  const [balance, setBalance] = useState(null);
  const [error, setError] = useState('');

  const connectWallet = async () => {
    try {
      setError('');

      // Clean up key and add '0x' if not present
      let key = privateKey.trim();
      if (!key.match(/^[0-9a-fA-F]{64}$/)) {
        throw new Error('Private key must be 64 hex characters.');
      }
      if (!key.startsWith('0x')) {
        key = '0x' + key;
      }

      const userWallet = new ethers.Wallet(key);
      const provider = new BrowserProvider(window.ethereum || ethers.getDefaultProvider());
      const connectedWallet = userWallet.connect(provider);

      const balanceBigInt = await provider.getBalance(connectedWallet.address);
      const balanceInEth = ethers.formatEther(balanceBigInt);

      setWallet(connectedWallet);
      setBalance(balanceInEth);
    } catch (err) {
      console.error(err);
      setError('Invalid private key or connection issue.');
    }
  };

  return (
    <div style={{ padding: '2rem', fontFamily: 'Arial' }}>
      <h2>Access Your Wallet</h2>

      <input
        type="text"
        placeholder="Enter your private key"
        value={privateKey}
        onChange={(e) => setPrivateKey(e.target.value)}
        style={{ width: '100%', padding: '10px', marginBottom: '10px' }}
      />

      <button onClick={connectWallet} style={{ padding: '10px 20px', fontSize: '16px' }}>
        Connect Wallet
      </button>

      {error && <p style={{ color: 'red' }}>{error}</p>}

      {wallet && (
        <div style={{ marginTop: '20px' }}>
          <p><strong>Address:</strong> {wallet.address}</p>
          <p><strong>ETH Balance:</strong> {balance} ETH</p>
          {/* Tokens and NFT preview will be added next */}
        </div>
      )}
    </div>
  );
}

export default WalletPage;
